input.newString:
function setStatus(id: number, status: 'fulfilled' | 'deleted'): ListingRow | undefined {
  const db = getDb();
  const listing = db.select().from(listings).where(eq(listings.id, id)).get();
  if (!listing) {
    return undefined;
  }
  const current = listing.status;
  const legalTransitions: Record<string, Set<string>> = {
    active: new Set(['fulfilled', 'deleted']),
    fulfilled: new Set(['deleted']),
  };
  const allowed = legalTransitions[current];
  if (!allowed || !allowed.has(status)) {
    throw new Error(
      `Listing #${id} cannot transition from '${current}' to '${status}'`,
    );
  }
  db.update(listings).set({ status, updatedAt: now() }).where(eq(listings.id, id)).run();
  return getListingById(id);
}

