describe('setStatus status transitions', () => {
  // Helper to build a row with a specific status
  function seedListing(status: 'active' | 'fulfilled' | 'deleted' | 'expired') {
    seedServer();
    const db = getDb();
    const past = Date.now() - 60_000;
    const row = db
      .insert(listings)
      .values({
        serverId: '200',
        userId: 'u1',
        username: 'alice',
        intent: 'have',
        accepts: 'cash',
        game: 'mtg',
        cardName: 'Black Lotus',
        cardNameNormalized: 'black lotus',
        cardSet: null,
        cardImageUrl: null,
        finish: null,
        variant: null,
        collectorNumber: null,
        manapoolUrl: null,
        condition: 'nm',
        priceCents: 1000,
        quantity: 1,
        notes: null,
        status,
        expiresAt: past + 30 * 24 * 3600 * 1000,
        createdAt: past,
        updatedAt: past,
      })
      .returning()
      .get();
    return { row, db };
  }

  it('active -> fulfilled is allowed and updates status', () => {
    const { row } = seedListing('active');
    const result = fulfillListing(row.id);
    expect(result?.status).toBe('fulfilled');
    expect(getListingById(row.id)?.status).toBe('fulfilled');
  });

  it('active -> deleted is allowed and updates status', () => {
    const { row } = seedListing('active');
    const result = softDeleteListing(row.id);
    expect(result?.status).toBe('deleted');
    expect(getListingById(row.id)?.status).toBe('deleted');
  });

  it('fulfilled -> deleted is allowed and updates status', () => {
    const { row } = seedListing('fulfilled');
    const result = softDeleteListing(row.id);
    expect(result?.status).toBe('deleted');
    expect(getListingById(row.id)?.status).toBe('deleted');
  });

  it('fulfilling an already fulfilled listing throws', () => {
    const { row } = seedListing('fulfilled');
    const before = getListingById(row.id);
    expect(() => fulfillListing(row.id)).toThrow(/cannot transition from/);
    expect(getListingById(row.id)?.status).toBe(before?.status);
  });

  it('deleting an already deleted listing throws', () => {
    const { row } = seedListing('deleted');
    const before = getListingById(row.id);
    expect(() => softDeleteListing(row.id)).toThrow(/cannot transition from/);
    expect(getListingById(row.id)?.status).toBe(before?.status);
  });

  it('fulfilling an expired listing throws', () => {
    const { row } = seedListing('expired');
    const before = getListingById(row.id);
    expect(() => fulfillListing(row.id)).toThrow(/cannot transition from/);
    expect(getListingById(row.id)?.status).toBe(before?.status);
  });

  it('deleting an expired listing throws', () => {
    const { row } = seedListing('expired');
    const before = getListingById(row.id);
    expect(() => softDeleteListing(row.id)).toThrow(/cannot transition from/);
    expect(getListingById(row.id)?.status).toBe(before?.status);
  });

  it('fulfilling a deleted listing throws', () => {
    const { row } = seedListing('deleted');
    const before = getListingById(row.id);
    expect(() => fulfillListing(row.id)).toThrow(/cannot transition from/);
    expect(getListingById(row.id)?.status).toBe(before?.status);
  });

  it('deleting a fulfilled listing throws when the guard is in place', () => {
    // This tests the "fulfilled -> fulfilled" blocked path: attempting to
    // soft-delete (which sets status='deleted') on a listing already 'deleted'
    // is tested above; here we test fulfilled -> fulfilled via fulfill.
    seedServer();
    const { row } = seedListing('fulfilled');
    const before = getListingById(row.id);
    expect(() => fulfillListing(row.id)).toThrow(/cannot transition from/);
    expect(getListingById(row.id)?.status).toBe(before?.status);
  });
});

